import requests, re, numpy as np, matplotlib.pyplot as plt
S=requests.Session(); S.headers.update({"User-Agent":"openscientist/1.0"})
ACC={"ppgn-1 (G5EDB6)":"G5EDB6","spg-7 (Q9N3T5)":"Q9N3T5","AFG3L2 (Q9Y4W6)":"Q9Y4W6","SPG7 (Q9UQ90)":"Q9UQ90"}
seqs={k:"".join(S.get(f"https://rest.uniprot.org/uniprotkb/{a}.fasta",timeout=60).text.strip().split("\n")[1:]) for k,a in ACC.items()}
KD={'A':1.8,'R':-4.5,'N':-3.5,'D':-3.5,'C':2.5,'Q':-3.5,'E':-3.5,'G':-0.4,'H':-3.2,'I':4.5,'L':3.8,
    'K':-3.9,'M':1.9,'F':2.8,'P':-1.6,'S':-0.8,'T':-0.7,'W':-0.9,'Y':-1.3,'V':4.2}
def hydro(s,w=19):
    v=np.array([KD.get(c,0) for c in s]); return np.convolve(v,np.ones(w)/w,mode="same")
UP={"ppgn-1 (G5EDB6)":[(111,133),(225,245)],"spg-7 (Q9N3T5)":[(119,139),(231,251)],
    "AFG3L2 (Q9Y4W6)":[(143,163),(251,271)],"SPG7 (Q9UQ90)":[(145,165),(249,269)]}
fig,axes=plt.subplots(4,1,figsize=(11,9),sharex=False)
print("Kyte-Doolittle window-19 peaks (threshold 1.0, >=15 residues):")
for ax,(k,s) in zip(axes,seqs.items()):
    h=hydro(s); ax.plot(h,lw=0.9,color="#333333"); ax.axhline(1.0,color="crimson",ls="--",lw=0.8)
    segs=[]; i=0
    while i<len(h):
        if h[i]>1.0:
            j=i
            while j<len(h) and h[j]>1.0: j+=1
            if j-i>=15: segs.append((i+1,j))
            i=j
        else: i+=1
    for a_,b_ in UP[k]: ax.axvspan(a_,b_,color="#2166ac",alpha=0.25)
    for a_,b_ in segs: ax.axvspan(a_,b_,color="#e08214",alpha=0.30)
    ax.set_ylabel("KD");ax.set_title(f"{k}   predicted peaks {segs}   UniProt TM {UP[k]}",fontsize=9,loc="left")
    ax.set_xlim(0,len(s)); ax.spines[['top','right']].set_visible(False)
    print(f"  {k:18s} peaks={segs}  UniProt TM={UP[k]}")
axes[-1].set_xlabel("residue")
plt.suptitle("Hydropathy: all four subunits have exactly two hydrophobic segments in the same N-terminal region (blue = UniProt TM, orange = predicted peak)",fontsize=10)
plt.tight_layout(); plt.show()

print("\nN-terminal 60 residues (mitochondrial targeting sequence region):")
for k,s in seqs.items():
    nt=s[:60]; R=nt.count('R');K=nt.count('K');DE=nt.count('D')+nt.count('E')
    print(f"  {k:18s} R={R} K={K} D+E={DE} net charge={R+K-DE:+d}  Arg/60={R/60:.2f}")
    print(f"      {nt}")
